/* ===== Numeria Quest — Lyra & Selena: party cerita setelah 5 misi guild =====
   SKILL REKAN (baru, lihat blok "SKILL" di bawah; angka di SKL / SKS / ULT_S):
   - SELENA (mirip hero Penyihir, efek dari skill_fx.js): Lingkaran Sihir, Bola Api, Sinar Petir, Hujan Es (membekukan),
     Penyembuhan (menggantikan Kegelapan: memulihkan HP hero/rekan yang paling lemah), Penguatan (menggantikan Cahaya:
     +25% damage hero & rekan 10 detik), ULTI Ledakan Arkana (efek Explosion).
   - LYRA: Tebasan Angin, Dash Maju, Lempar Belati + Teleport, Tusuk lalu Petir Menyambar, Serangan Membabi Buta,
     ULTI Kloning Bayangan (5 klon, masing-masing mewarisi 25% Kekuatan/Critical/Penetrasi Lyra, bertahan ~10 detik).
   - Energi ulti tiap rekan terisi saat memukul / terkena serangan, tersimpan di F.duoS (d.ult), penuh = 100.
   Pasang di index.html SETELAH semua script lain (paling akhir, sesudah enemy_ai.js):
     <script src="duo_lyra_selena.js"></script>

   Alur baru:
   - Setelah pemain menyelesaikan 5 misi guild (Chapter 1 selesai), Lyra (Assassin) dan Selena (Penyihir)
     menunggu di aula Rumah Guild. Bicara dengan salah satunya (atau Kapten Lyra) -> adegan pertemuan.
   - Bila pemain memilih "Ajak mereka", keduanya langsung bergabung dan party terbentuk (F.duo = 1).
   - Petualang lain di aula disembunyikan (ubah HIDE_OTHERS ke false kalau mau tetap bisa direkrut).
   - Lyra & Selena ditambahkan di AKHIR ROSTER (indeks 8 dan 9) jadi save lama (F.pm) tetap aman.

   Yang dipakai dari kode yang sudah ada (semuanya terlihat di party.js):
   ROSTER, MAXP, PM, F, EN, N, SP, mkNpc, dlg, ui, say, idle, hud, SND, meet, saveParty, rowName, ROLEIC.
   Kunci F baru: F.duo (1 = sudah bergabung). Syarat adegan: F.ch2 (Chapter 1 selesai) atau claimed() >= 5.

   DESAIN BARU (sesuai Lyra_dan_Selena__Lembar_Karakter_Pixel_Fantasi.png):
   - Lyra (Assassin) dan Selena (Penyihir) memakai pixel art 96x128 px, diambil langsung dari figur utama di lembar karakter
     (tudung gelap + jubah marun + pisau; topi penyihir ungu + tongkat orb biru). Lyra ini BUKAN Kapten Lyra.
   - Ukuran di dunia dan di battle/arena disamakan dengan hero (hero_pixel.js): dunia = NPC_WORLD_H x skala,
     battle = 128 x KRK_SEJ_SKALA x hs (hs diambil otomatis dari pemanggilan heroB, jadi arena hs=5 ikut membesar).
   - Dua gambar di bawah adalah PNG base64 96x128. Titik pijak (tengah kedua kaki) ada di DUO_AX. */
(() => {
  if (
    typeof ROSTER === "undefined" ||
    typeof mkNpc !== "function" ||
    typeof dlg !== "function" ||
    typeof EN === "undefined" ||
    !EN.I
  ) {
    console.warn("[duo_lyra_selena] dilewati: ROSTER / mkNpc / dlg / EN.I tidak ditemukan");
    return;
  }

  /* ---------- pengaturan ---------- */
  const HIDE_OTHERS = true; // true = 8 petualang lama disembunyikan dari aula
  const SPOT_SELENA = [9, 6]; // posisi Selena di aula Rumah Guild (peta "I"); geser kalau menabrak meja
  const SPOT_LYRA = [10, 6]; // posisi Lyra setelah (kalau) dikeluarkan dari party lalu kembali ke aula

  /* ---------- syarat: 5 misi guild selesai ---------- */
  const ready = () => {
    try {
      return !!F.ch2 || (typeof claimed === "function" && claimed() >= 5);
    } catch (e) {
      return !!F.ch2;
    }
  };

  /* ---------- sprite kecil cadangan (minimap / sebelum PNG termuat) ---------- */
  SP.m8 = mkNpc(
    {
      H: "#1c1624", // rambut hitam
      h: "#4a3a52",
      A: "#2a2230", // tudung & jubah gelap
      a: "#15101c",
      X: "#c0305a", // aksen merah marun
      T: "#3a2f42",
      t: "#1f1827",
      V: "#e8a0b0", // lapisan jubah merah muda
      P: "#2a2230",
      p: "#15101c",
    },
    "hood",
    true,
  );
  SP.m9 = mkNpc(
    {
      H: "#c9c4e8", // rambut perak keunguan
      h: "#eeeaff",
      A: "#2c2550", // topi & gaun ungu tua
      a: "#1a1535",
      X: "#d9a84a", // pita emas topi
      T: "#3a2f6a",
      t: "#241d48",
      V: "#b9a6f0", // hiasan ungu muda
      P: "#2c2550",
      p: "#1a1535",
    },
    "witch",
    false,
  );

  /* ---------- pixel art 96x128 (dari lembar karakter) ---------- */
  const DUO_PNG = {
    m8: "",
    m9: "",
  };
  const DUO_AX = { m8: 58, m9: 51 }; // kolom titik pijak (tengah kedua kaki) pada kanvas 96 lebar
  const DW = 96,
    DH = 128;
  const BATTLE_SCALE = 1; // 1 = persis setinggi hero di battle/arena; ubah kalau mau sedikit lebih kecil/besar
  const HERO_SK = typeof KRK_SEJ_SKALA !== "undefined" ? KRK_SEJ_SKALA : 0.3; // sama dengan hero_pixel.js
  const DUO = {};
  Object.keys(DUO_PNG).forEach((k) => {
    const o = (DUO[k] = { ready: false, tint: null });
    const img = new Image();
    img.onload = () => {
      const c = document.createElement("canvas");
      c.width = DW;
      c.height = DH;
      c.getContext("2d").drawImage(img, 0, 0);
      o.idle = c;
      o.ready = true;
    };
    img.src = "data:image/png;base64," + DUO_PNG[k];
  });
  const duoWhite = (o) => {
    if (o.tint) return o.tint;
    const c = document.createElement("canvas");
    c.width = DW;
    c.height = DH;
    const x = c.getContext("2d");
    x.drawImage(o.idle, 0, 0);
    x.globalCompositeOperation = "source-in";
    x.fillStyle = "#fff";
    x.fillRect(0, 0, DW, DH);
    return (o.tint = c);
  };

  /* hs terakhir yang dipakai hero (3 = battle biasa, 5 = arena) supaya ukuran duo selalu sama dengan hero */
  let lastHS = 3,
    inBattle = false;
  const hookHero = () => {
    try {
      if (typeof heroB === "function" && !heroB._duo) {
        const h = heroB;
        heroB = function (x, y, a, col, hs) {
          lastHS = hs || 3;
          return h.apply(this, arguments);
        };
        heroB._duo = 1;
      }
    } catch (e) {}
  };
  hookHero();
  if (typeof fmUnits === "function") {
    const _fu = fmUnits; // dipanggil tiap frame battle sebelum rekan digambar
    fmUnits = function () {
      inBattle = true;
      hookHero();
      queueMicrotask(() => {
        inBattle = false;
      });
      return _fu.apply(this, arguments);
    };
  }

  /* gambar sprite m8 / m9: dunia = ukuran hero di dunia, battle = ukuran hero di battle/arena */
  if (typeof spr === "function") {
    const _spr = spr;
    spr = function (k, x, y, s, al = 1, tint, fr = 0, fl = 0, mm) {
      const o = DUO[k];
      if (!o || !o.ready || mm) return _spr(k, x, y, s, al, tint, fr, fl, mm); // minimap / belum siap: sprite kecil lama
      const sc = typeof SC === "number" && SC > 0 ? SC : 1,
        q = (v) => Math.round(v * sc) / sc;
      let f, bob = 0;
      if (inBattle) {
        f = lastHS * HERO_SK * BATTLE_SCALE * (s / 3); // sama dengan heroB: hs x KRK_SEJ_SKALA
      } else {
        const H = typeof NPC_WORLD_H === "number" ? NPC_WORLD_H : 24 * (typeof KRK_DUNIA_SKALA !== "undefined" ? KRK_DUNIA_SKALA : 1);
        f = (H * s) / DH; // 128 baris = tinggi hero di dunia
        bob = fr ? -Math.round(s * 0.6) : 0;
      }
      const ax = DUO_AX[k],
        cx = q(x + 8 * s),
        foot = y - 8 * s + 24 * s + bob, // garis pijak kaki (sama dengan hero)
        X0 = q(cx - ax * f),
        X1 = q(cx - ax * f + DW * f),
        Y0 = q(foot - DH * f),
        Y1 = q(foot),
        sm = ctx.imageSmoothingEnabled,
        sq = ctx.imageSmoothingQuality;
      ctx.imageSmoothingEnabled = !inBattle && sc > 1.01;
      ctx.imageSmoothingQuality = "high";
      ctx.save();
      ctx.globalAlpha = al;
      if (fl) {
        ctx.translate(cx, 0);
        ctx.scale(-1, 1);
        ctx.translate(-cx, 0);
      }
      ctx.drawImage(tint ? duoWhite(o) : o.idle, 0, 0, DW, DH, X0, Y0, X1 - X0, Y1 - Y0);
      ctx.restore();
      ctx.globalAlpha = 1;
      ctx.imageSmoothingEnabled = sm;
      ctx.imageSmoothingQuality = sq;
    };
  }

  /* ---------- data anggota ---------- */
  const LYRA = {
    n: "Lyra",
    r: "Assassin",
    atk: 4,
    def: 0,
    cr: 0.3,
    sp: "m8",
    role: "assassin",
    row: "front",
    d: "Assassin · barisan depan · menusuk cepat, peluang kritis tinggi",
    t: "Lebih baik bayangan daripada sorotan. Tugas selesai, itu yang penting.",
    o: { B: "#c0305a", h: "#f0a8bc" },
  };
  const SELENA = {
    n: "Selena",
    r: "Penyihir",
    atk: 6,
    def: 0,
    cr: 0.15,
    sp: "m9",
    role: "mage",
    row: "back",
    d: "Penyihir bintang · barisan belakang · sihir jarak jauh (kekuatan +4)",
    t: "Dunia ini penuh misteri. Dan aku ingin melihat semuanya, bahkan hal yang tak terlihat.",
    o: { B: "#6a4fd0", h: "#b9a6f0" },
  };
  if (typeof ROLEIC !== "undefined") ROLEIC.assassin = "†";

  /* daftarkan ke ROSTER + NPC aula (pola sama seperti party.js) */
  [
    [LYRA, SPOT_LYRA],
    [SELENA, SPOT_SELENA],
  ].forEach(([m, spot]) => {
    ROSTER.push(m);
    m.id = "adv" + (ROSTER.length - 1);
    const isSelena = m === SELENA;
    EN.I.push({
      t: "npc",
      id: m.id,
      x: spot[0],
      y: spot[1],
      sp: m.sp,
      // Selena menunggu di aula sebelum adegan. Lyra memakai NPC "Kapten Lyra" yang sudah ada sebagai pemicu.
      on: () =>
        isSelena
          ? (ready() && !F.duo) || (!!F.duo && !PM.includes(m))
          : !!F.duo && !PM.includes(m),
    });
    N[m.id] = () => (!F.duo && ready() ? duoScene() : meet(m));
  });

  /* ---------- sembunyikan petualang lama ---------- */
  if (HIDE_OTHERS) {
    EN.I.forEach((e) => {
      if (e.t === "npc" && /^adv[0-7]$/.test(e.id || "")) e.on = () => false;
    });
  }

  /* ---------- Kapten Lyra (NPC lama) = Lyra si assassin ---------- */
  Object.values(EN).forEach((list) =>
    (list || []).forEach((e) => {
      if (e && e.id === "lyra") {
        const old = e.on;
        e.on = () => (old ? old() : true) && !F.duo; // setelah bergabung, jangan ada dua Lyra
      }
    }),
  );
  const _lyra = N.lyra;
  N.lyra = () => (!F.duo && ready() ? duoScene() : _lyra ? _lyra() : null);

  /* ---------- adegan pertemuan ---------- */
  function duoScene() {
    dlg(
      "Lyra",
      [
        "Lima misi guild, semuanya beres tanpa keluhan. Aku sudah memperhatikanmu dari bayangan sejak misi pertama.",
        "Lebih baik bayangan daripada sorotan. Tugas selesai, itu yang penting. Dan kamu menyelesaikan tugasmu.",
      ],
      () =>
        dlg(
          "Selena",
          [
            "Jadi ini orangnya. Dunia ini penuh misteri, dan aku ingin melihat semuanya, bahkan hal yang tak terlihat.",
            "Perjalanan sendirian terlalu sepi untuk melihat sejauh itu. Bolehkah kami berdua ikut denganmu?",
          ],
          () =>
            dlg(
              "Lyra",
              [
                "Aku di barisan depan, pisauku cepat dan sunyi. Selena menjaga dari belakang dengan sihirnya.",
                "Keputusan ada di tanganmu.",
              ],
              duoChoice,
            ),
        ),
    );
  }

  function duoChoice() {
    busy = true;
    say("Lyra dan Selena menunggu jawabanmu.");
    ui(
      `<div class="card"><b class="ok">Lyra</b> · Assassin <span class="qm">(Depan)</span><br><b class="ok">Selena</b> · Penyihir <span class="qm">(Belakang)</span><div class="qm">Mereka akan bergabung sebagai party-mu.</div><div class="row" style="margin-top:8px"><button class="b" id="duoy">Ajak mereka</button><button class="b g" id="duon">Nanti dulu</button></div></div>`,
    );
    $("#duon").onclick = idle;
    $("#duoy").onclick = duoJoin;
    $("#duoy").focus();
  }

  function duoJoin() {
    // save lama: bila party sudah penuh, rekan paling awal pulang ke guild supaya ada tempat untuk keduanya
    while (PM.length > MAXP - 2) PM.shift();
    [LYRA, SELENA].forEach((m) => {
      if (!PM.includes(m)) PM.push(m);
    });
    saveParty();
    F.duo = 1;
    if (globalThis.DUOBT) ["lyra", "selena"].forEach((k) => DUOBT.data(k)); // data rekan dibuat sekarang: level = level hero
    trail = [0, 1, 2, 3].map(() => [px, py]);
    SND.sfx("quest");
    hud();
    dlg("Lyra", ["Kami ikut. Pastikan kamu tidak memperlambat kami."], () =>
      dlg(
        "Selena",
        ["Mohon bantuannya. Semoga perjalanan ini membawa kita ke banyak hal yang belum terlihat."],
        () => {
          idle();
          if (typeof refreshBtn === "function") refreshBtn();
          say(`Lyra dan Selena bergabung! Party kini ${PM.length + 1} orang. Bagi poin status mereka lewat tombol ☻ Rekan di menu.`);
        },
      ),
    );
  }

  /* =====================================================================================
     BATTLE REAL-TIME + STATUS REKAN: Lyra & Selena bertarung seperti hero (HP, Mana, XP, level, 5 stat)
     - LYRA  : petarung JARAK DEKAT. Lari cepat, RADIUS SERANGAN (cincin merah muda di tanah), menusuk 2x lalu mundur,
               bisa LOMPAT (2x). Bila Mana cukup: "Tusukan Bayangan" (3 tusukan, x1.3, memakai Mana).
     - SELENA: penyihir JARAK JAUH. Menjaga jarak, mengisi sihir, menembakkan bola sihir (memakai Mana).
     - NYAWA : HP & Mana MEREKA TERPISAH dari hero dan TERBAWA antar battle (tidak pulih otomatis tiap battle).
               Pulih lewat: Ramuan di panel ☻ Rekan, naik level, hero pulih penuh (penginapan dsb.), atau perlahan di luar battle.
               HP 0 = tumbang sampai battle selesai, lalu siuman dengan 25% HP.
     - STATS : sama seperti hero — Kekuatan, HP maks, Mana maks, Critical, Penetrasi. Tiap naik level +3 poin (SP_LV),
               dibagi pemain lewat tombol "☻ Rekan" di menu (hanya di luar battle). Ada "Bagi otomatis" & "Reset poin".
     - XP    : tiap menang battle mereka dapat 80% XP musuh (level naik bila XP >= level x 30, sama dengan hero).
     - MUSUH : memilih sasaran TERDEKAT (pemain / Lyra / Selena) -> enemy_ai.js memanggil DUOBT.list() & DUOBT.attack(id).
     Data disimpan di F.duoS (ikut disimpan bersama flag F lain). Atur angka dasar di BC. */
  const BC = {
    lyra: {
      spd: 6.4, // kecepatan lari (px/frame) — hero jalan ~3, musuh biasa ~3
      reach: 130, // RADIUS SERANGAN: badan Lyra -> tepi musuh (px); hero pedang = 190
      base: { hp: 70, hpLv: 8, mp: 40, mpLv: 4, pw: 6, pwLv: 1.0, cr: 30, pe: 5 }, // nilai dasar + per level
      cd: [26, 44], // jeda antar rangkaian serangan (frame)
      hits: [5, 12], // frame tusukan dalam satu rangkaian biasa
      shadowHits: [4, 9, 14], // Tusukan Bayangan
      shadowMp: 18, // biaya Mana Tusukan Bayangan
      gainMp: 2, // Mana didapat tiap rangkaian biasa
      regen: 0.05, // pemulihan Mana (per frame)
      dodge: 0.8, // peluang melompat menghindari serangan
      auto: ["pw", "cr", "hp", "pw", "pe", "hp"], // urutan "Bagi otomatis"
    },
    selena: {
      spd: 2.8,
      keep: [300, 470], // jarak ideal ke musuh (px)
      range: 640, // jarak maksimum menembak
      base: { hp: 55, hpLv: 6, mp: 70, mpLv: 6, pw: 10, pwLv: 1.2, cr: 15, pe: 5 },
      cd: [110, 150],
      cast: 22, // lama mengisi sihir (frame)
      castMp: 8, // biaya Mana per bola sihir
      shot: 10, // kecepatan bola sihir (px/frame)
      regen: 0.08,
      dodge: 0.6,
      auto: ["pw", "mp", "cr", "pw", "hp", "mp"],
    },
  };
  const SPT = typeof SP_LV === "number" ? SP_LV : 3, // poin per level (sama dengan hero)
    CRX = typeof CRIT_X === "number" ? CRIT_X : 2,
    PNX = typeof PEN_X === "number" ? PEN_X : 1.25;
  const DB = { S: null, list: [], duo: [], stash: null, eproj: [], sproj: [], later: [], wproj: [], dproj: [], fx: [], clones: [], buff: null, t: 0, tab: "lyra" };
  const plv = () => (typeof Pl !== "undefined" && Pl && Pl.lv) || 1;
  const rnd = (a, b) => a + Math.random() * (b - a);
  const ex0 = () => EHX() - ((S && S.eo) || 0); // pusat musuh (koordinat asli)
  const gapOf = (u) => Math.abs(ex0() - u.x) - 16 * S.e.s; // jarak badan unit -> tepi musuh
  const cxm = (x) => (MIRX ? VW - x : x); // asli -> kanonik (ruang gambar)
  const liveFight = () =>
    !!(S && S.e && DB.S === S && S.ehp > 0 && !S.dead && (mode === "m" || mode === "r" || mode === "q"));
  const keyOf = (m) => (m === LYRA ? "lyra" : "selena"),
    mOf = (k) => (k === "lyra" ? LYRA : SELENA),
    isDuo = (m) => m === LYRA || m === SELENA;

  /* ---------- data & rumus stat (meniru hero di script.js) ---------- */
  const mhpOf = (k, d) => Math.round(BC[k].base.hp + BC[k].base.hpLv * (d.lv - 1) + 10 * d.st.hp),
    mmpOf = (k, d) => Math.round(BC[k].base.mp + BC[k].base.mpLv * (d.lv - 1) + 5 * d.st.mp),
    pwrOf = (k, d) => BC[k].base.pw + BC[k].base.pwLv * d.lv + 2 * d.st.pw,
    critOf = (k, d) => Math.min(75, BC[k].base.cr + 0.5 * (d.lv - 1) + 1.5 * d.st.cr),
    penOf = (k, d) => Math.min(75, BC[k].base.pe + 0.5 * (d.lv - 1) + 1.5 * d.st.pe);
  function rec(k) {
    if (!F.duoS) F.duoS = {};
    let d = F.duoS[k];
    if (!d) {
      const lv = plv();
      d = F.duoS[k] = { lv, xp: 0, sp: (lv - 1) * SPT, st: {}, hp: 0, mp: 0 };
      d.st = { pw: 0, cr: 0, pe: 0, hp: 0, mp: 0 };
      d.hp = mhpOf(k, d);
      d.mp = mmpOf(k, d);
    }
    d.st = { pw: 0, cr: 0, pe: 0, hp: 0, mp: 0, ...d.st };
    if (typeof d.ult !== "number") d.ult = 0;
    d.hp = clamp(d.hp, 0, mhpOf(k, d));
    d.mp = clamp(d.mp, 0, mmpOf(k, d));
    return d;
  }
  const bothK = ["lyra", "selena"];

  /* ---------- stash: selama battle, Lyra & Selena dikeluarkan dari PM supaya logika party bawaan
     (fmUnits / fmAttack di party.js) tidak menggambar & menyerang dobel. Dipulihkan saat battle selesai. ---------- */
  function stashDuo() {
    if (DB.stash || typeof PM === "undefined") return;
    const d = PM.filter(isDuo);
    if (!d.length) return;
    DB.stash = PM.slice();
    DB.duo = d;
    for (let i = PM.length - 1; i >= 0; i--) if (isDuo(PM[i])) PM.splice(i, 1);
  }
  function unstashDuo() {
    if (DB.stash) {
      PM.length = 0;
      DB.stash.forEach((m) => PM.push(m));
      DB.stash = null;
    }
    DB.duo = [];
    DB.S = null;
    DB.list = [];
    DB.eproj = [];
    DB.sproj = [];
    resetSk();
  }
  if (typeof setBt === "function") {
    const _sb = setBt;
    setBt = function (v) {
      const was = btOn,
        r = _sb.apply(this, arguments);
      if (v && !was) stashDuo();
      else if (!v && was) unstashDuo();
      return r;
    };
  }
  if (typeof saveParty === "function") {
    const _sv = saveParty; // simpan party selalu dengan Lyra & Selena ikut, walau sedang battle
    saveParty = function () {
      const had = !!DB.stash;
      if (had) {
        const keep = DB.stash.slice();
        PM.length = 0;
        keep.forEach((m) => PM.push(m));
        DB.stash = null;
      }
      try {
        return _sv.apply(this, arguments);
      } finally {
        if (had) stashDuo();
      }
    };
  }
  if (typeof fmAttack === "function") {
    const _fa = fmAttack; // party kosong (hanya duo) -> langsung selesai, jangan menggantung menunggu animasi
    fmAttack = function (done) {
      if (DB.stash && !PM.length && typeof done === "function") return done();
      return _fa.apply(this, arguments);
    };
  }

  /* ---------- unit battle (HP/Mana menempel ke data F.duoS: terbawa antar battle) ---------- */
  function ensure() {
    if (DB.S === S) return;
    DB.S = S;
    DB.list = [];
    DB.eproj = [];
    DB.sproj = [];
    resetSk();
    DB.t = performance.now();
    if (!S || !S.e) return;
    DB.duo.forEach((m) => {
      const k = keyOf(m),
        d = rec(k),
        u = {
          id: m.id, m, k: m.sp, key: k, c: BC[k], d,
          x: clamp(PMr - (m === LYRA ? 70 : 160), 44, VW - 44),
          face: 1, jy: 0, jv: 0, jn: 0, kv: 0,
          cd: rnd(20, 50), hurt: 0, ft: Math.random() * 100,
          atk: null, cast: null, back: 0, hop: 0, evd: false, down: false, run: 0, trail: [], scd: {}, sk: null, ultMsg: d.ult >= 100 ? 1 : 0,
        };
      Object.defineProperties(u, {
        hp: { get: () => d.hp, set: (v) => (d.hp = clamp(v, 0, mhpOf(k, d))) },
        mp: { get: () => d.mp, set: (v) => (d.mp = clamp(v, 0, mmpOf(k, d))) },
        mhp: { get: () => mhpOf(k, d) },
        mmp: { get: () => mmpOf(k, d) },
      });
      if (d.hp <= 0) d.hp = Math.ceil(mhpOf(k, d) * 0.25); // sisa dari kekalahan sebelumnya: siuman dulu
      DB.list.push(u);
    });
  }
  const mv = (u, d) => (u.x = clamp(u.x + d, 44, VW - 44));
  function jump(u) {
    if (u.jn >= 2) return;
    u.jv = u.jn ? JUMP.v2 : JUMP.v1;
    u.jn++;
    SND.sfx("whoosh");
    if (!rm)
      for (let i = 0; i < 7; i++)
        an.pt.push({ x: cxm(u.x) + R(-12, 12), y: GY - 4 - u.jy, vx: (Math.random() - 0.5) * 3, vy: -Math.random() * 1.2, l: 16, c: u.jn === 2 ? "#7cf0ff" : "#ffe9b0" });
  }
  const flAt = (x, t, c, dy = 0) => an.fl.push({ x, y: 104 + dy, t, c, l: 60 });

  /* damage rekan: Kekuatan x acak, Critical (x CRIT_X) & Penetrasi (x PEN_X) seperti hero */
  function roll(u, mult = 1) {
    const crit = Math.random() * 100 < critOf(u.key, u.d),
      pen = Math.random() * 100 < penOf(u.key, u.d);
    let v = pwrOf(u.key, u.d) * rnd(0.85, 1.15) * mult * buffM();
    if (crit) v *= CRX;
    if (pen) v *= PNX;
    return { d: Math.max(1, Math.round(v)), crit, pen };
  }

  /* menghindari serangan musuh yang membidik unit ini */
  function evade(u, gap, rg) {
    if (S.ph !== 2) u.evd = false;
    if (u.jy > 0 || u.jn >= 2) return;
    if (!rg && S.ph === 2 && S.tid === u.id && S.tel <= 12 && !u.evd && gap <= MELEE.hit + 50) {
      u.evd = true; // tebasan mendarat ~10 frame setelah aba-aba -> lompat tepat sebelum itu
      if (Math.random() < u.c.dodge) jump(u);
    }
    if (rg)
      for (const p of DB.eproj)
        if (p.u === u && p.d >= 0 && !p.jd && Math.abs(p.x - u.x) < 90) {
          p.jd = 1;
          if (Math.random() < u.c.dodge) jump(u);
        }
  }

  /* serangan unit ke musuh */
  function hitEnemy(u, r, col, ug) {
    if (!S || S.ehp <= 0 || S.dead || mode === "w" || mode === "x") return;
    S.ehp -= r.d;
    if (u.d && ug !== 0) gainU(u, ug == null ? (r.crit ? 5 : 3) : ug);
    S.aiSoftDmg = (S.aiSoftDmg || 0) + r.d; // enemy_ai: pukulan rekan = ringan (tidak memotong aba-aba)
    S.cfrom = u.x;
    SND.sfx("hit");
    SND.mon(S.e.sp, "hurt");
    an.se = Math.max(an.se || 0, r.crit ? 14 : 8);
    if (!rm) {
      burst(ecx(), 165, r.pen ? "#7cf0ff" : col);
      if (r.crit) burst(ecx(), 150, "#ffffff");
    }
    flAt(ecx() - 3 + R(-26, 26), (r.crit ? "KRITIS " : r.pen ? "TEMBUS " : "") + r.d, r.crit ? "#ffd166" : r.pen ? "#7cf0ff" : col, R(0, 22));
    bars();
    if (S.ehp <= 0 && !S.dq) {
      S.dq = 1;
      setTimeout(win, 800);
    }
  }
  function strikeL(u, n, dir, mult, sh) {
    const c = u.c,
      gap = gapOf(u);
    if (gap > c.reach + 18) return flAt(cxm(u.x), "MELESET", "#cfd8e8", 20);
    const r = roll(u, mult),
      cd = MIRX ? -dir : dir,
      col = sh ? "#c06bff" : "#ff7aa6";
    SND.sfx("whoosh");
    if (typeof slashFx === "function") slashFx(r.crit ? "#ffd166" : col, "c", ecx(), 150 + R(-14, 14), sh ? 0.8 : 0.65, cd < 0 ? 1 : 0, n % 2 ? 0.5 : -0.5);
    hitEnemy(u, r, col);
  }
  function fireS(u, dir) {
    u.mp -= u.c.castMp;
    SND.sfx("whoosh");
    DB.sproj.push({ x: u.x + dir * 30, dir, u });
  }

  /* AI Lyra: kejar -> masuk radius -> 2x tusuk (atau Tusukan Bayangan) -> mundur -> ulangi; melompat bila perlu */
  function aiLyra(u, dt) {
    const c = u.c, rg = enemyAtk(S.e).t === "ranged",
      dir = ex0() >= u.x ? 1 : -1,
      gap = gapOf(u);
    u.face = dir;
    if (u.sk) return lyraSk(u, dt, dir, gap);
    if (!u.atk) evade(u, gap, rg);
    if (u.atk) {
      const a = u.atk;
      a.t += dt;
      if (a.t < 14 && gap > 14) {
        mv(u, dir * Math.min(9 * dt, gap - 14)); // lunge ke depan
        u.run = 2;
      }
      while (a.n < a.h.length && a.t >= a.h[a.n]) strikeL(u, a.n++, dir, a.sh ? 1.3 : 1, a.sh);
      if (a.t >= a.tot) {
        u.atk = null;
        if (!a.sh) u.mp += c.gainMp;
        u.cd = rnd(c.cd[0], c.cd[1]);
        u.back = rnd(10, 18);
      }
      return;
    }
    if (u.back > 0) {
      u.back -= dt; // hit-and-run: mundur sebentar setelah menusuk
      mv(u, -dir * c.spd * 0.85 * dt);
      u.run = 1;
      return;
    }
    if (!u.atk) {
      const ks = pickL(u, gap);
      if (ks) return startL(u, ks);
    }
    u.hop = Math.max(0, u.hop - dt);
    if (gap > c.reach * 0.78) {
      mv(u, dir * Math.min(c.spd * dt, Math.max(0, gap - c.reach * 0.6)));
      u.run = 1;
      if (gap > 360 && u.jy === 0 && u.hop <= 0) {
        jump(u);
        u.hop = 70;
      } else if (gap > 520 && u.jn === 1 && u.jv < 2 && u.hop <= 40) jump(u); // lompat ke-2 di puncak
    } else if (gap < c.reach * 0.3) {
      mv(u, -dir * c.spd * 0.6 * dt);
      u.run = 1;
    }
    if (gap <= c.reach && u.cd <= 0) {
      const sh = u.mp >= c.shadowMp;
      if (sh) {
        u.mp -= c.shadowMp;
        flAt(cxm(u.x), "Tusukan Bayangan", "#c06bff", -26);
      }
      u.atk = { t: 0, n: 0, sh, h: sh ? c.shadowHits : c.hits, tot: sh ? 27 : 22 };
    }
  }
  /* AI Selena: jaga jarak, isi sihir (butuh Mana), tembak */
  function aiSelena(u, dt) {
    const c = u.c, rg = enemyAtk(S.e).t === "ranged",
      dir = ex0() >= u.x ? 1 : -1,
      gap = gapOf(u);
    u.face = dir;
    if (!u.cast) evade(u, gap, rg);
    if (u.cast) {
      u.cast.t += dt;
      if (u.cast.t >= u.cast.n) {
        const sk = u.cast.sk;
        u.cast = null;
        if (sk) castS(u, sk, dir);
        else {
          fireS(u, dir);
          u.cd = rnd(c.cd[0], c.cd[1]);
        }
      }
      return;
    }
    if (gap < c.keep[0]) {
      mv(u, -dir * c.spd * dt);
      u.run = 1;
    } else if (gap > c.keep[1]) {
      mv(u, dir * c.spd * dt);
      u.run = 1;
    }
    const ks = pickS(u, gap);
    if (ks) {
      u.cast = { t: 0, n: ks.cast, sk: ks };
      return;
    }
    if (u.cd <= 0 && gap <= c.range && u.mp >= c.castMp) u.cast = { t: 0, n: c.cast };
  }

  function tickDuo(dt) {
    const alive = S.ehp > 0 && !S.dead,
      pl = DB.list;
    pl.forEach((u) => {
      u.hurt = Math.max(0, u.hurt - dt);
      u.cd = Math.max(0, u.cd - dt);
      Object.keys(u.scd).forEach((id) => (u.scd[id] = Math.max(0, u.scd[id] - dt)));
      u.ft += dt;
      u.run = 0;
      if (u.hp > 0) u.mp += u.c.regen * dt;
      if (u.jy > 0 || u.jv > 0) {
        u.jv -= JUMP.g * dt;
        u.jy += u.jv * dt;
        if (u.jy <= 0) u.jy = u.jv = u.jn = 0;
      }
      if (Math.abs(u.kv) > 0.2) {
        mv(u, u.kv * dt);
        u.kv *= Math.pow(0.8, dt);
      } else u.kv = 0;
      if (u.hp <= 0) return;
      if (alive) (u.m === LYRA ? aiLyra : aiSelena)(u, dt);
      // jangan menumpuk di atas pemain / rekan lain
      const sep = (x, w) => {
        const d = u.x - x;
        if (Math.abs(d) < w) mv(u, (d >= 0 ? 1 : -1) * Math.min(2.2 * dt, w - Math.abs(d)));
      };
      sep(PMr, 46);
      pl.forEach((o) => o !== u && o.hp > 0 && sep(o.x, 40));
      if (!rm && (u.run === 2 || (u.m === LYRA && u.run && u.jy === 0 && u.ft % 6 < dt + 0.01))) u.trail.push({ x: u.x, jy: u.jy, t: 7 });
      u.trail.forEach((g) => (g.t -= dt));
      u.trail = u.trail.filter((g) => g.t > 0);
    });
    tickSkills(dt, alive);
    // bola sihir Selena
    DB.sproj = DB.sproj.filter((p) => {
      if (!alive) return false;
      p.x += p.dir * (p.speed || p.u.c.shot) * dt;
      const e = ex0(),
        hw = 16 * S.e.s + 8;
      if ((p.dir > 0 && p.x >= e - hw) || (p.dir < 0 && p.x <= e + hw)) {
        hitEnemy(p.u, roll(p.u, p.mult || 1), p.col || "#9ad0ff");
        if (p.fx) fxPush("mxf", ecx(), effY(), { delay: 0 });
        return false;
      }
      return p.x > 0 && p.x < VW;
    });
    // tembakan musuh jarak jauh yang membidik rekan
    DB.eproj = DB.eproj.filter((p) => {
      if (p.d < 0) return (p.d += dt), true;
      const u = p.u;
      p.dir = u.x >= p.x ? 1 : -1;
      p.x += p.dir * 5.5 * dt;
      if (Math.abs(p.x - u.x) <= 14) {
        p.land(u.hp <= 0 ? "MELESET!" : u.jy >= JUMP.clr ? "LOMPAT!" : null);
        return false;
      }
      return true;
    });
  }

  /* musuh menyerang rekan (dipanggil enemy_ai.js: enemyAct). true = sudah ditangani */
  function attackUnit(id) {
    ensure();
    const u = DB.list.find((x) => x.id === id && x.hp > 0);
    if (!u || !S || !S.e) return false;
    const e = S.e,
      T = enemyAtk(e),
      rg = T.t === "ranged",
      n = rg ? T.n || 1 : 1,
      fz = (S.freeze > 0 ? 0.6 : 1) * (S.wet > 0 ? 0.75 : 1),
      d = Math.max(1, Math.round((R(e.atk - 2, e.atk + 2) - Math.floor(u.d.lv * 0.5)) * fz)),
      per = Math.max(1, Math.round(d * (n === 1 ? 1 : 1.3 / n))),
      S0 = S;
    if (S.freeze > 0) S.freeze--;
    if (S.wet > 0) S.wet--;
    an.wt = 0;
    SND.mon(e.sp, "atk");
    say(rg ? `${e.n} membidik ${u.m.n}!` : `${e.n} menyerang ${u.m.n}!`);
    S.shots = n;
    S.vh = false;
    const finish = () => {
      if (S !== S0) return;
      enemyDone();
      if (mode === "m" || mode === "r") menu();
    };
    const land = (ev) => {
      if (S !== S0 || mode === "w" || mode === "x" || Pl.hp <= 0) return;
      const last = --S.shots <= 0;
      if (ev) {
        flAt(cxm(u.x), ev, "#7cf0ff", -10);
        if (last) {
          if (!S.vh) say(ev === "MELESET!" ? `Serangan ${e.n} meleset dari ${u.m.n}!` : `${u.m.n} menghindari serangan ${e.n}!`);
          finish();
        }
        return;
      }
      S.vh = true;
      hurtUnit(u, per);
      if (last) finish();
    };
    if (rg) {
      an.rc = 14;
      for (let i = 0; i < n; i++) DB.eproj.push({ x: ex0(), dir: u.x >= ex0() ? 1 : -1, d: -i * 12, u, T, land });
    } else {
      an.lg = 18;
      setTimeout(() => land(u.hp <= 0 || Math.abs(ex0() - u.x) - 16 * S0.e.s > MELEE.hit ? "MELESET!" : u.jy >= JUMP.clr ? "LOMPAT!" : null), 170);
    }
    return true;
  }
  function hurtUnit(u, d) {
    u.hp -= d;
    u.hurt = 14;
    u.kv = (u.x >= ex0() ? 1 : -1) * 5;
    u.atk = null;
    u.cast = null;
    if (!(u.sk && (u.sk.id === "frenzy" || u.sk.id === "clone"))) u.sk = null; // frenzy & ulti tidak bisa dipotong
    if (u.hp > 0) gainU(u, 8);
    SND.sfx("hurt");
    if (!rm) burst(cxm(u.x), 150, "#ff6b8b");
    flAt(cxm(u.x), "-" + d, "#ff6b8b", -10);
    say(`${S.e.n} mengenai ${u.m.n}! −${d} HP (${Math.round(u.hp)}/${u.mhp})`);
    if (u.hp <= 0) {
      u.sk = null;
      u.cast = null;
      u.down = true;
      u.jy = u.jv = u.jn = 0;
      SND.sfx("tick");
      say(`${u.m.n} tumbang! Dia siuman setelah battle selesai.`);
    }
  }

  /* menang: XP untuk rekan (80% XP musuh), yang tumbang siuman 25% HP, level naik = poin status + pulih penuh */
  function awardXp() {
    const xp = Math.round(((S.e && S.e.xp) || 0) * 0.8),
      msg = [];
    DB.list.forEach((u) => {
      const d = u.d,
        k = u.key;
      if (d.hp <= 0) d.hp = Math.ceil(mhpOf(k, d) * 0.25);
      d.xp += xp;
      while (d.xp >= d.lv * 30) {
        d.xp -= d.lv * 30;
        d.lv++;
        d.sp += SPT;
        d.hp = mhpOf(k, d);
        d.mp = mmpOf(k, d);
        msg.push(`<b class="ok">${u.m.n} naik ke Level ${d.lv}!</b> +${SPT} poin status`);
        flAt(cxm(u.x), "LEVEL UP!", "#ffd166", -30);
      }
      u.down = false;
    });
    if (!DB.list.length) return;
    const card = document.querySelector("#ui .card");
    if (card)
      card.insertAdjacentHTML(
        "beforeend",
        `<div class="qm">${DB.list.map((u) => u.m.n).join(" & ")} +${xp} XP${msg.length ? " · " + msg.join(" · ") + " (buka ☻ Rekan)" : ""}</div>`,
      );
    refreshBtn();
  }

  /* ---------- gambar ---------- */
  function drawDuo(now) {
    const hsz = DH * lastHS * HERO_SK * BATTLE_SCALE; // tinggi sprite di layar
    const order = DB.list.slice().sort((a, b) => (a.m === SELENA ? 0 : 1) - (b.m === SELENA ? 0 : 1));
    const pi = inBattle;
    inBattle = true; // spr() memakai ukuran hero battle
    order.forEach((u) => {
      const xc = cxm(u.x),
        cd = MIRX ? -u.face : u.face,
        fl = cd < 0 ? 1 : 0,
        bob = u.down || u.jy > 0 ? 0 : u.run ? Math.round(Math.abs(Math.sin(u.ft * 0.55)) * 4) : Math.round(Math.sin(now / 300 + u.ft) * 2),
        foot = GY - u.jy - bob;
      ctx.save();
      if (!rm) {
        const jk = Math.max(0.45, 1 - u.jy / 140);
        ctx.fillStyle = "rgba(0,0,0,.35)";
        ctx.beginPath();
        ctx.ellipse(xc, GY + 3, 34 * jk, 6 * jk, 0, 0, 6.283);
        ctx.fill();
        // cincin radius serangan Lyra
        if (!u.down && u.m === LYRA && liveFight()) {
          const inR = gapOf(u) <= u.c.reach;
          ctx.save();
          ctx.globalAlpha = inR ? 0.5 : 0.2;
          ctx.strokeStyle = inR ? "#ff7aa6" : "#ffffff";
          ctx.lineWidth = 2;
          ctx.setLineDash([10, 8]);
          ctx.beginPath();
          ctx.ellipse(xc, GY + 3, u.c.reach, 16, 0, 0, 6.283);
          ctx.stroke();
          ctx.restore();
        }
        u.trail.forEach((g) => spr(u.k, cxm(g.x) - 24, GY - g.jy - 48, 3, 0.2 * (g.t / 7), "#ffb3cc", 0, fl));
      }
      let tilt = 0, ox = 0, al = 1;
      if (u.down) {
        tilt = -1.25 * (cd || 1);
        al = 0.5;
      } else {
        if (u.run) tilt = 0.1 * (cd || 1) * (u.run === 2 ? 1.6 : 1);
        if (u.atk && u.atk.t < 14) ox = cd * Math.min(10, u.atk.t * 2);
        if (u.cast) tilt = -0.05 * cd;
        if (u.hurt > 0) ox -= cd * Math.min(8, u.hurt);
      }
      ctx.translate(xc, foot);
      ctx.rotate(tilt);
      ctx.translate(-xc, -foot);
      spr(u.k, xc - 24 + ox, foot - 48, 3, al, u.hurt > 6 && !rm ? "#ffffff" : null, 0, fl);
      ctx.restore();
      if (u.cast && !rm) {
        const k = u.cast.t / (u.cast.n || BC.selena.cast),
          ox2 = xc + cd * 34,
          oy = foot - hsz * 0.62;
        ctx.save();
        ctx.fillStyle = (u.cast.sk && u.cast.sk.col) || "#9ad0ff";
        [20, 12, 6].forEach((r) => {
          ctx.globalAlpha = 0.18 + 0.25 * k;
          ctx.beginPath();
          ctx.arc(ox2, oy, r * (0.5 + k), 0, 6.283);
          ctx.fill();
        });
        ctx.restore();
      }
      // nama + level + bar HP & Mana
      if (!u.down) {
        const bw = 64,
          by = foot - hsz - 8;
        ctx.save();
        ctx.fillStyle = "rgba(0,0,0,.6)";
        ctx.fillRect(xc - bw / 2 - 1, by - 1, bw + 2, 16);
        ctx.fillStyle = u.hp / u.mhp > 0.35 ? "#4de07a" : "#ff5d73";
        ctx.fillRect(xc - bw / 2, by, Math.round((bw * u.hp) / u.mhp), 6);
        ctx.fillStyle = "#4db8ff";
        ctx.fillRect(xc - bw / 2, by + 7, Math.round((bw * u.mp) / u.mmp), 3);
        ctx.fillStyle = u.d.ult >= 100 ? "#ffd166" : "#a07a2a";
        ctx.fillRect(xc - bw / 2, by + 11, Math.round((bw * Math.min(100, u.d.ult || 0)) / 100), 3);
        ctx.font = 'bold 14px "Pixelify Sans",monospace';
        ctx.textAlign = "center";
        ctx.lineWidth = 3;
        ctx.strokeStyle = "#000";
        ctx.fillStyle = "#fff";
        ctx.strokeText(`${u.m.n} Lv${u.d.lv}`, xc, by - 5);
        ctx.fillText(`${u.m.n} Lv${u.d.lv}`, xc, by - 5);
        ctx.restore();
      }
    });
    inBattle = pi;
    drawSkFx(now);
    ctx.save();
    DB.sproj.forEach((p) => {
      const x = cxm(p.x),
        y = GY - 100;
      ctx.fillStyle = p.col || "#9ad0ff";
      [16, 10, 5].map((v) => v * (p.big ? 1.8 : 1)).forEach((r) => {
        ctx.globalAlpha = 0.35;
        ctx.beginPath();
        ctx.arc(x, y, r, 0, 6.283);
        ctx.fill();
      });
      ctx.globalAlpha = 1;
      ctx.fillStyle = "#fff";
      ctx.fillRect(x - 3, y - 3, 6, 6);
      if (!rm && an.pt.length < 90) {
        const dc = MIRX ? -p.dir : p.dir;
        an.pt.push({ x: x - dc * 8, y: y + R(-6, 6), vx: -dc * 1.2, vy: (Math.random() - 0.5) * 1.2, l: 12, c: "#b9a6f0" });
      }
    });
    DB.eproj.forEach((p) => {
      if (p.d < 0) return;
      const x = cxm(p.x),
        col = (p.T && p.T.col) || "#ff6b8b";
      ctx.fillStyle = col;
      ctx.globalAlpha = 0.4;
      ctx.beginPath();
      ctx.arc(x, GY - 90, 13, 0, 6.283);
      ctx.fill();
      ctx.globalAlpha = 1;
      ctx.beginPath();
      ctx.arc(x, GY - 90, 7, 0, 6.283);
      ctx.fill();
    });
    ctx.restore();
  }

  /* ---------- HUD battle: HP & Mana rekan di bawah bar hero (memakai kelas .bar yang sudah ada) ---------- */
  let hudEl = null,
    hudKey = "";
  function updHud() {
    if (!hudEl) {
      const host = document.querySelector(".hb.pl");
      if (!host) return;
      hudEl = document.createElement("div");
      hudEl.id = "duoh";
      hudEl.style.display = "none";
      host.appendChild(hudEl);
    }
    const on = btOn && DB.list.length > 0;
    if (!on) {
      if (hudKey !== "off") {
        hudEl.style.display = "none";
        hudKey = "off";
      }
      return;
    }
    const k = DB.list.map((u) => `${u.m.n}|${u.d.lv}|${Math.round(u.hp)}|${u.mhp}|${Math.round(u.mp)}|${u.mmp}|${Math.round(u.d.ult || 0)}`).join(";");
    if (k === hudKey) return;
    hudKey = k;
    hudEl.style.display = "";
    hudEl.innerHTML = DB.list
      .map(
        (u) =>
          `<small>${u.m.n} Lv${u.d.lv} — HP ${Math.round(u.hp)}/${u.mhp}, Mana ${Math.round(u.mp)}/${u.mmp}</small><div class="bar hp"><i style="width:${(u.hp / u.mhp) * 100}%"></i></div><div class="bar fp"><i style="width:${(u.mp / u.mmp) * 100}%"></i></div><div class="bar ult"><i style="width:${Math.min(100, u.d.ult || 0)}%"></i></div>`,
      )
      .join("");
  }

  /* dipanggil tiap frame battle dari draw() lewat enemyShots (script.js memanggilnya tanpa syarat) */
  function duoFrame() {
    if (!S || !S.e || !btOn) return;
    ensure();
    const now = performance.now();
    let dt = Math.min(3, (now - DB.t) / 16.667);
    DB.t = now;
    if (an.hs > 0 || (typeof UIX !== "undefined" && UIX.open)) dt = 0;
    dt *= typeof ts === "number" ? ts : 1;
    if (dt > 0 && liveFight()) tickDuo(dt);
    else if (!(S.ehp > 0) || S.dead || mode === "w" || mode === "x") DB.eproj.length = DB.sproj.length = 0;
    if ((mode === "w" || mode === "x") && DB.buff) expireBuff();
    if (mode === "w" && !S.duoXp && DB.list.length) {
      S.duoXp = 1;
      awardXp();
    }
    if (DB.list.length) drawDuo(now);
    updHud();
  }
  if (typeof enemyShots === "function") {
    const _es = enemyShots;
    enemyShots = function () {
      const r = _es.apply(this, arguments);
      try {
        duoFrame();
      } catch (err) {
        console.error("[duo_lyra_selena] battle:", err);
      }
      return r;
    };
  } else console.warn("[duo_lyra_selena] enemyShots tidak ditemukan: Lyra & Selena tidak bisa digambar di battle");


  /* =====================================================================================
     SKILL REKAN. Semua angka di SKL (Lyra), SKS (Selena), ULT_S. mp = biaya Mana, cd = jeda (frame), mult = pengali damage.
     Efek memakai efek skill_fx.js lewat antrean an.sf (mxc Lingkaran Sihir, mxf Bola Api, mxb Sinar, mxi Hujan Es,
     mxu Explosion, sxd Dash, axl Petir menyambar); efek tambahan (angin, belati, teleport, heal, penguatan) digambar di drawSkFx. */
  const SKS = {
    circle: { id: "circle", n: "Lingkaran Sihir", mp: 22, cd: 300, mult: 1.7, cast: 30, col: "#ff9a3d" },
    fball: { id: "fball", n: "Bola Api", mp: 22, cd: 260, mult: 1.6, cast: 30, col: "#ff7a3a" },
    beam: { id: "beam", n: "Sinar Petir", mp: 25, cd: 320, mult: 1.5, cast: 34, col: "#ffe14d" },
    ice: { id: "ice", n: "Hujan Es", mp: 25, cd: 340, mult: 0.55, cast: 30, col: "#7cf0ff" }, // 3 pecahan x mult
    heal: { id: "heal", n: "Penyembuhan", mp: 28, cd: 520, cast: 36, col: "#7ef0c8", pw: 2.2, pct: 0.12 }, // heal = Kekuatan x pw + pct x HP maks target
    buff: { id: "buff", n: "Penguatan", mp: 30, cd: 1100, cast: 36, col: "#ffe28a", dur: 600, pct: 0.25 }, // +25% damage selama dur frame
  };
  const ULT_S = { id: "ult", n: "Ledakan Arkana", mp: 0, cd: 0, cast: 56, col: "#ff7a3a", x: 6 }; // total = Kekuatan x 6 (menembus pertahanan)
  const SKL = {
    wind: { id: "wind", n: "Tebasan Angin", mp: 14, cd: 200, mult: 1.1, col: "#8ff0c8" },
    dash: { id: "dash", n: "Dash Maju", mp: 12, cd: 220, mult: 1.5, col: "#ff7aa6" },
    dagger: { id: "dagger", n: "Belati & Teleport", mp: 20, cd: 320, mult: 0.9, col: "#d9a0ff" }, // lempar 0.9, lalu 2 tusukan 1.1 & 1.3
    thunder: { id: "thunder", n: "Tusuk Petir", mp: 24, cd: 360, mult: 1.2, col: "#ffe14d" }, // tusukan 1.2 + petir 1.1 (40% menyengat)
    frenzy: { id: "frenzy", n: "Membabi Buta", mp: 30, cd: 600, mult: 0.5, col: "#ff7aa6", hits: 14 },
    clone: { id: "clone", n: "Kloning Bayangan", mp: 0, cd: 0, col: "#c06bff", inherit: 0.25, life: 600 }, // ULTI: 5 klon (CLONE_N) x 25% atribut
  };
  const CLONE_N = 5;

  const buffM = () => (DB.buff && DB.buff.t > 0 ? 1.25 : 1);
  const effY = () => (typeof SKFX !== "undefined" ? SKFX.yc(SKFX.effH()) : 150);
  const hszNow = () => DH * lastHS * HERO_SK * BATTLE_SCALE;
  function fxPush(kind, x, y, ex = {}) {
    if (rm) return;
    if (typeof SKFX === "undefined") return slashFx("#ffd166", "c", x, 150, 1.1);
    an.sf.push(Object.assign({ t: ex.delay || 0, col: "#fff", kind, x, y, big: 1, flip: 0, rot: 0 }, ex));
  }
  function later(frames, fn) {
    DB.later.push({ t: frames, fn });
  }
  function resetSk() {
    expireBuff();
    DB.later = [];
    DB.wproj = [];
    DB.dproj = [];
    DB.fx = [];
    DB.clones = [];
  }
  function expireBuff() {
    if (DB.buff && typeof Pl !== "undefined") Pl.atk = (Pl.atk || 0) - DB.buff.amt;
    DB.buff = null;
  }
  function gainU(u, v) {
    if (!u.d) return;
    u.d.ult = Math.min(100, (u.d.ult || 0) + v);
    if (u.d.ult >= 100 && !u.ultMsg) {
      u.ultMsg = 1;
      flAt(cxm(u.x), "ULTI SIAP!", "#ffd166", -44);
      SND.sfx("quest");
    }
  }
  const skName = (u, sk) => {
    flAt(cxm(u.x), sk.n, sk.col, -30);
    say(`${u.m.n}: ${sk.n}!`);
  };
  /* damage skill = roll() biasa x mult (Critical / Penetrasi tetap berlaku) */
  const skHit = (u, mult, col, ug, pen) => {
    const r = roll(u, mult);
    if (pen) r.pen = true;
    hitEnemy(u, r, col, ug);
  };
  const flash = (x, col) => DB.fx.push({ k: "tp", x, t: 0, l: 22, col });

  /* ---------- SELENA ---------- */
  function healTarget() {
    let best = null,
      br = 0.55;
    if (Pl.hp > 0 && Pl.hp / mhp() < br) {
      br = Pl.hp / mhp();
      best = { id: "p", x: PMr };
    }
    DB.list.forEach((o) => {
      if (o.hp > 0 && o.hp / o.mhp < br) {
        br = o.hp / o.mhp;
        best = o;
      }
    });
    return best;
  }
  function pickS(u, gap) {
    const ready = (s) => u.mp >= s.mp && !(u.scd[s.id] > 0);
    if ((u.d.ult || 0) >= 100 && gap <= u.c.range) return ULT_S;
    if (healTarget() && ready(SKS.heal)) return SKS.heal;
    if (!(DB.buff && DB.buff.t > 0) && gap <= u.c.range && S.ehp > S.e.hp * 0.25 && ready(SKS.buff) && u.mp >= SKS.buff.mp + 8) return SKS.buff;
    if (u.cd <= 0 && gap <= u.c.range && Math.random() < 0.6) {
      const a = [SKS.circle, SKS.fball, SKS.beam, SKS.ice].filter(ready);
      if (a.length) return a[(Math.random() * a.length) | 0];
    }
    return null;
  }
  function castS(u, sk, dir) {
    if (!liveFight() || u.hp <= 0) return;
    const ult = sk === ULT_S;
    if (!ult && u.mp < sk.mp) return;
    if (sk.id === "heal" && !healTarget()) return;
    u.mp -= sk.mp;
    u.scd[sk.id] = sk.cd;
    skName(u, sk);
    const X = ecx(),
      Y = effY(),
      my = GY - hszNow() * 0.55,
      face = MIRX ? -dir : dir;
    if (!ult && sk.id !== "heal" && sk.id !== "buff") u.cd = rnd(u.c.cd[0], u.c.cd[1]) * 0.55;
    if (sk.id === "circle") {
      fxPush("mxc", X, GY);
      later(14, () => skHit(u, sk.mult, sk.col));
    } else if (sk.id === "fball") {
      DB.sproj.push({ x: u.x + dir * 30, dir, u, mult: sk.mult, col: "#ff8a3a", big: 1, fx: 1, speed: 11 });
    } else if (sk.id === "beam") {
      DB.fx.push({ k: "beam", x1: u.x + dir * 26, x2: ex0() - dir * 16 * S.e.s, y: my, t: 0, l: 16, col: sk.col });
      fxPush("mxb", X, Y, { delay: -5 });
      later(7, () => skHit(u, sk.mult, sk.col));
    } else if (sk.id === "ice") {
      for (let i = 0; i < 3; i++)
        later(i * 9 + 4, () => {
          fxPush("mxi", ecx() + R(-34, 34), GY, { fin: i === 2 ? 1 : 0 });
          skHit(u, sk.mult, sk.col);
          if (i === 2) {
            S.freeze = Math.max(S.freeze || 0, 2);
            flAt(ecx(), "BEKU", "#7cf0ff", 0);
          }
        });
    } else if (sk.id === "heal") {
      const t = healTarget(),
        tm = t.id === "p" ? mhp() : t.mhp,
        amt = Math.max(5, Math.round(pwrOf(u.key, u.d) * sk.pw + tm * sk.pct));
      if (t.id === "p") {
        Pl.hp = Math.min(mhp(), Pl.hp + amt);
        try {
          bars();
        } catch (e) {}
        try {
          hud();
        } catch (e) {}
      } else t.hp += amt;
      DB.fx.push({ k: "heal", x: t.x, t: 0, l: 56 });
      flAt(cxm(t.x), "+" + amt, "#7ef0c8", -8);
      SND.sfx("level");
      say(`${u.m.n} memulihkan ${t.id === "p" ? "kamu" : t.m.n} +${amt} HP.`);
    } else if (sk.id === "buff") {
      if (DB.buff) DB.buff.t = sk.dur;
      else {
        const amt = Math.max(2, Math.round(pwr() * sk.pct));
        Pl.atk = (Pl.atk || 0) + amt; // dikembalikan lagi saat buff habis / battle selesai (expireBuff)
        DB.buff = { t: sk.dur, amt };
      }
      [PMr].concat(DB.list.filter((o) => o.hp > 0).map((o) => o.x)).forEach((x) => DB.fx.push({ k: "buff", x, t: 0, l: 60 }));
      SND.sfx("quest");
      say(`Damage hero dan rekan +${Math.round(sk.pct * 100)}% selama ${Math.round(sk.dur / 60)} detik!`);
    } else if (ult) {
      u.d.ult = 0;
      u.ultMsg = 0;
      const total = Math.max(7, Math.round(pwrOf(u.key, u.d) * ULT_S.x * buffM()));
      for (let i = 0; i < 7; i++)
        later(i * 6 + 2, () => {
          const last = i === 6,
            d = Math.round(total * (last ? 0.4 : 0.1));
          fxPush("mxu", ecx() + (last ? 0 : R(-34, 34)), Y, { fin: last ? 1 : 0 });
          hitEnemy(u, { d, crit: last, pen: true }, "#ff9a3d", 0);
          an.se = Math.max(an.se || 0, last ? 26 : 12);
        });
      say(`${u.m.n}: ${ULT_S.n}! Total ${total} damage.`);
    }
  }

  /* ---------- LYRA ---------- */
  function pickL(u, gap) {
    const c = u.c,
      ok = (s) => u.mp >= s.mp && !(u.scd[s.id] > 0);
    if ((u.d.ult || 0) >= 100) return SKL.clone;
    if (u.cd > 0) return null;
    const L = [];
    if (gap <= c.reach) {
      if (ok(SKL.thunder)) L.push(SKL.thunder);
      if (ok(SKL.frenzy)) L.push(SKL.frenzy);
    } else {
      if (gap <= 560 && ok(SKL.wind)) L.push(SKL.wind);
      if (gap > 170 && gap <= 620 && ok(SKL.dash)) L.push(SKL.dash);
      if (gap > 200 && gap <= 640 && ok(SKL.dagger)) L.push(SKL.dagger);
    }
    if (!L.length || Math.random() > (gap <= c.reach ? 0.5 : 0.85)) return null;
    return L[(Math.random() * L.length) | 0];
  }
  function startL(u, sk) {
    u.mp -= sk.mp || 0;
    u.scd[sk.id] = sk.cd || 0;
    u.sk = { id: sk.id, t: 0, ph: 0, n: 0 };
    skName(u, sk);
    if (sk.id === "clone") {
      u.d.ult = 0;
      u.ultMsg = 0;
      flash(u.x, "#c06bff");
    }
  }
  function endSk(u) {
    u.sk = null;
    u.cd = rnd(u.c.cd[0], u.c.cd[1]);
    u.back = rnd(6, 12);
  }
  function windFire(u, dir, i) {
    if (!liveFight() || u.hp <= 0) return;
    SND.sfx("whoosh");
    DB.wproj.push({ x: u.x + dir * 30, y: GY - (i ? 100 : 62), dir, u, mult: SKL.wind.mult * (i ? 0.9 : 1) });
  }
  function throwDagger(u, dir) {
    SND.sfx("whoosh");
    DB.dproj.push({ x: u.x + dir * 24, dir, u, k: u.sk, ang: 0 });
  }
  function dashStrike(u, dir) {
    if (gapOf(u) > u.c.reach + 45) return flAt(cxm(u.x), "MELESET", "#cfd8e8", 20);
    SND.sfx("whoosh");
    if (typeof SKFX !== "undefined") slashFx("#ff3a2e", "sxd", ecx(), 150, 1.1, MIRX ? 1 : 0, -0.12, 0);
    else slashFx("#ff7aa6", "c", ecx(), 150, 1.2, 0, -0.4);
    skHit(u, SKL.dash.mult, SKL.dash.col);
  }
  function zap(u) {
    if (!liveFight()) return;
    fxPush("axl", ecx(), effY(), { fin: 1 });
    skHit(u, 1.1, "#ffe14d", 2, true);
    an.se = Math.max(an.se || 0, 14);
    if (Math.random() < 0.4) {
      S.stun = Math.max(S.stun || 0, 1);
      flAt(ecx(), "TERSENGAT", "#ffe14d", 0);
    }
  }
  function frenzyHit(u) {
    if (gapOf(u) > u.c.reach + 30) return flAt(cxm(u.x), "MELESET", "#cfd8e8", 20);
    SND.sfx("whoosh");
    slashFx("#ff7aa6", "c", ecx() + R(-26, 26), 150 + R(-44, 44), 0.7, Math.random() < 0.5 ? 1 : 0, R(-1, 1));
    skHit(u, SKL.frenzy.mult, SKL.frenzy.col, 1);
    u.x = clamp(u.x + R(-3, 3), 44, VW - 44);
  }
  function spawnClones(u) {
    for (let i = 0; i < CLONE_N; i++) {
      const x = clamp(u.x + (i - 2) * 46 + R(-8, 8), 44, VW - 44);
      DB.clones.push({ x, face: u.face, cd: rnd(6, 34), atk: null, ft: Math.random() * 100, life: SKL.clone.life, run: 0, u, jy: 0 });
      flash(x, "#c06bff");
    }
    SND.sfx("start");
    say(`Lyra membelah diri jadi ${CLONE_N}! Tiap klon mewarisi ${Math.round(SKL.clone.inherit * 100)}% atributnya.`);
  }
  function lyraSk(u, dt, dir, gap) {
    const k = u.sk,
      c = u.c;
    k.t += dt;
    switch (k.id) {
      case "wind":
        if (!k.f && k.t >= 10) {
          k.f = 1;
          windFire(u, dir, 0);
          later(7, () => windFire(u, dir, 1));
        }
        if (k.t >= 28) endSk(u);
        break;
      case "dash":
        if (k.ph === 0 && k.t >= 6) {
          k.ph = 1;
          k.t = 0;
          SND.sfx("whoosh");
        } else if (k.ph === 1) {
          if (gap > 30 && k.t < 26) {
            mv(u, dir * Math.min(28 * dt, Math.max(0, gap - 26)));
            u.run = 2;
          } else {
            k.ph = 2;
            k.t = 0;
            dashStrike(u, dir);
          }
        } else if (k.ph === 2 && k.t >= 16) endSk(u);
        break;
      case "dagger":
        if (k.ph === 0 && k.t >= 12) {
          k.ph = 1;
          k.t = 0;
          throwDagger(u, dir);
        } else if (k.ph === 1 && k.t > 90) endSk(u);
        else if (k.ph === 2) {
          if (!k.a && k.t >= 7) {
            k.a = 1;
            strikeL(u, 0, dir, 1.1, true);
          }
          if (!k.b && k.t >= 15) {
            k.b = 1;
            strikeL(u, 1, dir, 1.3, true);
          }
          if (k.t >= 28) endSk(u);
        }
        break;
      case "thunder":
        if (k.t < 8 && gap > 14) {
          mv(u, dir * Math.min(9 * dt, gap - 14));
          u.run = 2;
        }
        if (!k.a && k.t >= 8) {
          k.a = 1;
          strikeL(u, 0, dir, 1.2, false);
        }
        if (!k.b && k.t >= 18) {
          k.b = 1;
          zap(u);
        }
        if (k.t >= 34) endSk(u);
        break;
      case "frenzy":
        if (k.t >= 8 + k.n * 3 && k.n < SKL.frenzy.hits) {
          k.n++;
          frenzyHit(u);
        }
        if (k.n >= SKL.frenzy.hits && k.t >= 8 + SKL.frenzy.hits * 3 + 10) endSk(u);
        break;
      case "clone":
        if (!k.a && k.t >= 18) {
          k.a = 1;
          spawnClones(u);
        }
        if (k.t >= 34) endSk(u);
        break;
      default:
        endSk(u);
    }
  }
  /* klon Lyra: mewarisi 25% Kekuatan / Critical / Penetrasi Lyra */
  function cloneRoll(cl) {
    const u = cl.u,
      f = SKL.clone.inherit,
      crit = Math.random() * 100 < critOf(u.key, u.d) * f,
      pen = Math.random() * 100 < penOf(u.key, u.d) * f;
    let v = pwrOf(u.key, u.d) * f * rnd(0.85, 1.15) * buffM();
    if (crit) v *= CRX;
    if (pen) v *= PNX;
    return { d: Math.max(1, Math.round(v)), crit, pen };
  }

  /* ---------- tick skill: jadwal, proyektil, klon, efek, buff ---------- */
  function tickSkills(dt, alive) {
    if (DB.buff) {
      DB.buff.t -= dt;
      if (DB.buff.t <= 0) expireBuff();
    }
    if (!alive) {
      DB.later = [];
      DB.wproj = [];
      DB.dproj = [];
      DB.clones = [];
    }
    const due = [];
    DB.later = DB.later.filter((q) => {
      q.t -= dt;
      if (q.t <= 0) due.push(q);
      return q.t > 0;
    });
    due.forEach((q) => {
      if (liveFight()) q.fn();
    });
    // tebasan angin
    DB.wproj = DB.wproj.filter((p) => {
      p.x += p.dir * 14 * dt;
      if (!rm && an.pt.length < 90) an.pt.push({ x: cxm(p.x) - (MIRX ? -p.dir : p.dir) * 14, y: p.y + R(-16, 16), vx: -p.dir * 1.2, vy: R(-0.6, 0.6), l: 14, c: "#bff7e2" });
      if (Math.abs(ex0() - p.x) <= 16 * S.e.s + 10) {
        if (!rm) slashFx("#8ff0c8", "c", ecx(), p.y - 8, 1.1, p.dir < 0 ? 1 : 0, p.dir * 0.4);
        skHit(p.u, p.mult, "#8ff0c8");
        return false;
      }
      return p.x > 0 && p.x < VW;
    });
    // belati
    DB.dproj = DB.dproj.filter((p) => {
      if (p.u.sk !== p.k || p.u.hp <= 0) return false; // Lyra terpotong
      p.x += p.dir * 22 * dt;
      p.ang += 0.6 * dt;
      if (Math.abs(ex0() - p.x) <= 16 * S.e.s + 8) {
        skHit(p.u, SKL.dagger.mult, "#d9a0ff");
        flash(p.u.x, "#d9a0ff"); // teleport ke depan musuh
        p.u.x = clamp(ex0() - p.dir * (16 * S.e.s + 62), 44, VW - 44);
        p.u.face = p.dir;
        flash(p.u.x, "#d9a0ff");
        SND.sfx("whoosh");
        p.k.ph = 2;
        p.k.t = 0;
        return false;
      }
      return p.x > -40 && p.x < VW + 40;
    });
    // klon Lyra
    const reach = BC.lyra.reach;
    DB.clones = DB.clones.filter((cl) => {
      cl.life -= dt;
      if (cl.life <= 0) {
        flash(cl.x, "#c06bff");
        return false;
      }
      const dir = ex0() >= cl.x ? 1 : -1,
        gap = Math.abs(ex0() - cl.x) - 16 * S.e.s;
      cl.face = dir;
      cl.ft += dt;
      cl.run = 0;
      cl.cd -= dt;
      if (cl.atk) {
        cl.atk.t += dt;
        if (!cl.atk.d && cl.atk.t >= 5) {
          cl.atk.d = 1;
          if (gap <= reach + 18) {
            SND.sfx("whoosh");
            if (!rm) slashFx("#c06bff", "c", ecx(), 150 + R(-30, 30), 0.6, Math.random() < 0.5 ? 1 : 0, R(-0.8, 0.8));
            hitEnemy({ x: cl.x }, cloneRoll(cl), "#c06bff", 0);
          }
        }
        if (cl.atk.t >= 14) cl.atk = null;
        return true;
      }
      if (gap > reach * 0.7) {
        cl.x = clamp(cl.x + dir * Math.min(5.8 * dt, Math.max(0, gap - reach * 0.6)), 44, VW - 44);
        cl.run = 1;
      } else if (cl.cd <= 0) {
        cl.atk = { t: 0 };
        cl.cd = rnd(14, 26);
      }
      return true;
    });
    DB.fx = DB.fx.filter((f) => ((f.t += dt), f.t < f.l));
  }

  /* ---------- gambar efek tambahan ---------- */
  function drawSkFx(now) {
    if (!DB.fx.length && !DB.wproj.length && !DB.dproj.length && !DB.clones.length) return;
    const hsz = hszNow(),
      my = GY - hsz * 0.5;
    // klon (di belakang efek)
    const pi = inBattle;
    inBattle = true;
    DB.clones.forEach((cl) => {
      const xc = cxm(cl.x),
        cd = MIRX ? -cl.face : cl.face,
        fl = cd < 0 ? 1 : 0,
        fade = cl.life < 60 ? cl.life / 60 : 1,
        bob = cl.run ? Math.round(Math.abs(Math.sin(cl.ft * 0.55)) * 4) : Math.round(Math.sin(now / 300 + cl.ft) * 2),
        foot = GY - bob,
        ox = cl.atk && cl.atk.t < 8 ? cd * Math.min(10, cl.atk.t * 2) : 0;
      ctx.save();
      ctx.fillStyle = "rgba(120,40,200,.35)";
      ctx.beginPath();
      ctx.ellipse(xc, GY + 3, 30, 5, 0, 0, 6.283);
      ctx.fill();
      ctx.translate(xc, foot);
      ctx.rotate(cl.run ? 0.1 * (cd || 1) : 0);
      ctx.translate(-xc, -foot);
      spr("m8", xc - 24 + ox, foot - 48, 3, 0.58 * fade, null, 0, fl);
      ctx.globalCompositeOperation = "lighter";
      spr("m8", xc - 24 + ox, foot - 48, 3, 0.16 * fade, "#ffffff", 0, fl);
      ctx.restore();
    });
    inBattle = pi;
    DB.dproj.forEach((p) => {
      ctx.save();
      ctx.translate(cxm(p.x), GY - 95);
      ctx.rotate(p.ang);
      ctx.fillStyle = "#f2ecff";
      ctx.fillRect(-9, -2, 15, 4);
      ctx.fillStyle = "#8a63ff";
      ctx.fillRect(-14, -3, 5, 6);
      ctx.restore();
    });
    DB.wproj.forEach((p) => {
      const x = cxm(p.x),
        dc = MIRX ? -p.dir : p.dir,
        a0 = dc > 0 ? -0.95 : Math.PI - 0.95,
        a1 = dc > 0 ? 0.95 : Math.PI + 0.95;
      ctx.save();
      ctx.lineCap = "round";
      ctx.strokeStyle = "#5fe0b0";
      ctx.globalAlpha = 0.45;
      ctx.lineWidth = 11;
      ctx.beginPath();
      ctx.arc(x - dc * 22, p.y, 30, a0, a1);
      ctx.stroke();
      ctx.globalAlpha = 1;
      ctx.strokeStyle = "#e8fff6";
      ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.arc(x - dc * 22, p.y, 30, a0, a1);
      ctx.stroke();
      ctx.restore();
    });
    ctx.save();
    DB.fx.forEach((f) => {
      const k = Math.min(1, f.t / f.l),
        xc = cxm(f.x),
        cross = (px, py, r) => {
          ctx.fillRect(px - 1.5, py - r, 3, r * 2 + 1);
          ctx.fillRect(px - r, py - 1.5, r * 2 + 1, 3);
        };
      if (f.k === "heal") {
        ctx.globalAlpha = (1 - k) * 0.28;
        ctx.fillStyle = "#7ef0c8";
        ctx.beginPath();
        ctx.arc(xc, my, hsz * 0.6 * (0.7 + 0.3 * k), 0, 6.283);
        ctx.fill();
        ctx.globalAlpha = (1 - k) * 0.85;
        ctx.strokeStyle = "#7ef0c8";
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.ellipse(xc, GY + 3, 20 + 50 * k, 7 + 9 * k, 0, 0, 6.283);
        ctx.stroke();
        for (let i = 0; i < 8; i++) {
          const ph = (k * 1.3 + i / 8) % 1;
          ctx.globalAlpha = Math.sin(Math.PI * ph) * (1 - k * 0.5);
          ctx.fillStyle = i % 2 ? "#d8fff0" : "#7ef0c8";
          cross(xc + Math.sin(i * 2.4) * 28, GY - ph * hsz * 1.1, 4 + (i % 3));
        }
      } else if (f.k === "buff") {
        ctx.globalAlpha = (1 - k) * 0.22;
        ctx.fillStyle = "#ffd166";
        ctx.beginPath();
        ctx.arc(xc, my, hsz * 0.62 * (0.7 + 0.3 * k), 0, 6.283);
        ctx.fill();
        ctx.globalAlpha = (1 - k) * 0.9;
        ctx.strokeStyle = "#ffd166";
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.ellipse(xc, GY + 3, 22 + 44 * k, 7 + 8 * k, 0, 0, 6.283);
        ctx.stroke();
        for (let i = 0; i < 6; i++) {
          const ph = (k * 1.4 + i / 6) % 1,
            px = xc + ((i % 3) - 1) * 20,
            py = GY - ph * hsz * 1.15;
          ctx.globalAlpha = Math.sin(Math.PI * ph) * (1 - k * 0.4);
          ctx.strokeStyle = i % 2 ? "#fff0b0" : "#ffd166";
          ctx.lineWidth = 3;
          ctx.beginPath();
          ctx.moveTo(px - 7, py + 5);
          ctx.lineTo(px, py - 4);
          ctx.lineTo(px + 7, py + 5);
          ctx.stroke();
        }
      } else if (f.k === "tp") {
        ctx.globalAlpha = 1 - k;
        ctx.strokeStyle = f.col;
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.ellipse(xc, GY + 3, 10 + 44 * k, 4 + 8 * k, 0, 0, 6.283);
        ctx.stroke();
        ctx.fillStyle = "#f0d8ff";
        for (let i = 0; i < 6; i++) ctx.fillRect(xc - 18 + i * 7, GY - hsz * (0.15 + 0.85 * k) * (0.6 + 0.4 * ((i * 37) % 10) / 10), 3, 22 + 20 * (1 - k));
      } else if (f.k === "beam") {
        const x1 = cxm(f.x1),
          x2 = cxm(f.x2);
        ctx.lineCap = "round";
        ctx.globalAlpha = 1 - k * 0.7;
        ctx.strokeStyle = f.col;
        ctx.lineWidth = 16 * (1 - k) + 3;
        ctx.beginPath();
        ctx.moveTo(x1, f.y);
        ctx.lineTo(x2, f.y);
        ctx.stroke();
        ctx.strokeStyle = "#ffffff";
        ctx.lineWidth = 6 * (1 - k) + 1;
        ctx.beginPath();
        ctx.moveTo(x1, f.y);
        ctx.lineTo(x2, f.y);
        ctx.stroke();
      }
    });
    ctx.restore();
  }
  function skillInfo(k) {
    const L =
      k === "lyra"
        ? [SKL.wind, SKL.dash, SKL.dagger, SKL.thunder, SKL.frenzy].map((s) => s.n).concat(["ULTI: " + SKL.clone.n + " (5 klon, tiap klon 25% atribut Lyra)"])
        : [SKS.circle, SKS.fball, SKS.beam, SKS.ice, SKS.heal, SKS.buff].map((s) => s.n).concat(["ULTI: " + ULT_S.n]);
    const d = rec(k);
    return `<div class="qm" style="margin-top:8px"><b>Skill</b> (dipakai otomatis saat battle) · Energi ulti ${Math.round(d.ult || 0)}/100<br>${L.join(" · ")}</div>`;
  }

  /* ---------- panel ☻ Rekan: atur stat, ramuan ---------- */
  const joined = () => !!F.duo;
  function statUpD(k, s) {
    const d = rec(k);
    if (d.sp <= 0 || !(s in d.st)) return false;
    d.sp--;
    d.st[s]++;
    if (s === "hp") d.hp += 10;
    if (s === "mp") d.mp += 5;
    d.hp = Math.min(d.hp, mhpOf(k, d));
    d.mp = Math.min(d.mp, mmpOf(k, d));
    return true;
  }
  function resetD(k) {
    const d = rec(k);
    d.sp += d.st.pw + d.st.cr + d.st.pe + d.st.hp + d.st.mp;
    d.st = { pw: 0, cr: 0, pe: 0, hp: 0, mp: 0 };
    d.hp = Math.min(d.hp, mhpOf(k, d));
    d.mp = Math.min(d.mp, mmpOf(k, d));
  }
  function autoD(k) {
    const d = rec(k),
      seq = BC[k].auto;
    for (let i = 0; d.sp > 0; i++) statUpD(k, seq[i % seq.length]);
  }
  function potD(k, kind) {
    const d = rec(k);
    if (kind === "hp") {
      if (!Pl.pot || d.hp >= mhpOf(k, d)) return false;
      Pl.pot--;
      d.hp = Math.min(mhpOf(k, d), d.hp + 40);
    } else {
      if (!Pl.fpot || d.mp >= mmpOf(k, d)) return false;
      Pl.fpot--;
      d.mp = Math.min(mmpOf(k, d), d.mp + 40);
    }
    try {
      hud();
    } catch (e) {}
    return true;
  }
  let ov = null,
    btn = null;
  const totalSp = () => (joined() ? bothK.reduce((a, k) => a + rec(k).sp, 0) : 0);
  function refreshBtn() {
    if (!btn) {
      const nav = document.querySelector("nav.menu");
      if (!nav) return;
      btn = document.createElement("button");
      btn.className = "b g";
      btn.id = "bduo";
      btn.type = "button";
      btn.onclick = openPanel;
      nav.appendChild(btn);
    }
    btn.style.display = joined() && !btOn ? "" : "none";
    const n = totalSp();
    btn.textContent = "☻ Rekan" + (n ? ` (${n})` : "");
  }
  function panelHtml() {
    const k = DB.tab,
      d = rec(k),
      m = mOf(k),
      rows = [
        ["pw", "Kekuatan", Math.round(pwrOf(k, d)), "+2 damage dasar"],
        ["hp", "HP maks", mhpOf(k, d), "+10 HP maks"],
        ["mp", "Mana maks", mmpOf(k, d), "+5 Mana maks"],
        ["cr", "Peluang Critical", +critOf(k, d).toFixed(1) + "%", "+1,5%"],
        ["pe", "Peluang Penetrasi", +penOf(k, d).toFixed(1) + "%", "+1,5%"],
      ],
      tabs = bothK
        .map((t) => `<button type="button" class="b ${t === k ? "" : "g"}" data-t="${t}">${mOf(t).n}${rec(t).sp ? ` (${rec(t).sp})` : ""}</button>`)
        .join(" ");
    return (
      `<h2 style="margin:0 0 6px">Status Rekan</h2><div class="row" style="margin-bottom:6px">${tabs}</div>` +
      `<div class="qm" style="margin-bottom:4px"><b>${m.n}</b> · ${m.r} · Lv${d.lv} · XP ${d.xp}/${d.lv * 30}<div class="bar ult"><i style="width:${(d.xp / (d.lv * 30)) * 100}%"></i></div>` +
      `HP ${Math.round(d.hp)}/${mhpOf(k, d)} · Mana ${Math.round(d.mp)}/${mmpOf(k, d)}<br>Poin tersisa: <b class="${d.sp ? "ok" : ""}">${d.sp}</b> · tiap level +${SPT} poin. Critical ×${CRX}, Penetrasi ×${PNX}. Maks 75%.</div>` +
      rows
        .map(
          ([s, n, v, t]) =>
            `<div class="irow"><div><b>${n}: ${v}</b><br><small>Tiap poin ${t} · sudah dialokasikan ${d.st[s]}</small></div><button class="b" data-s="${s}" ${d.sp ? "" : "disabled"}>+</button></div>`,
        )
        .join("") +
      skillInfo(k) +
      `<div class="row" style="margin-top:8px"><button class="b g" data-a="hp" ${Pl.pot && d.hp < mhpOf(k, d) ? "" : "disabled"}>Ramuan HP ×${Pl.pot || 0}</button> <button class="b g" data-a="mp" ${Pl.fpot && d.mp < mmpOf(k, d) ? "" : "disabled"}>Ramuan Mana ×${Pl.fpot || 0}</button></div>` +
      `<div class="row" style="margin-top:8px"><button class="b g" data-a="auto" ${d.sp ? "" : "disabled"}>Bagi otomatis</button> <button class="b g" data-a="reset">Reset poin</button> <button class="b" data-a="x">Tutup</button></div>`
    );
  }
  function drawPanel() {
    ov.firstChild.innerHTML = panelHtml();
  }
  const closePanel = () => {
    if (ov) ov.style.display = "none";
    refreshBtn();
  };
  function openPanel() {
    if (btOn || !joined()) return void say("Status rekan hanya bisa diatur di luar battle.");
    if (!ov) {
      ov = document.createElement("div");
      ov.style.cssText = "position:fixed;inset:0;z-index:99;background:rgba(0,0,0,.62);display:none;align-items:center;justify-content:center";
      ov.innerHTML = '<div class="card" style="width:min(520px,92vw);max-height:88vh;overflow:auto"></div>';
      ov.addEventListener("click", (e) => {
        if (e.target === ov) return closePanel();
        const b = e.target.closest && e.target.closest("button");
        if (!b || b.disabled) return;
        const k = DB.tab;
        if (b.dataset.t) DB.tab = b.dataset.t;
        else if (b.dataset.s) statUpD(k, b.dataset.s);
        else if (b.dataset.a === "x") return closePanel();
        else if (b.dataset.a === "auto") autoD(k);
        else if (b.dataset.a === "reset") resetD(k);
        else if (b.dataset.a) potD(k, b.dataset.a);
        SND.sfx("tick");
        drawPanel();
      });
      document.body.appendChild(ov);
      // selama panel terbuka, tombol keyboard tidak boleh menggerakkan hero di belakangnya
      document.addEventListener(
        "keydown",
        (e) => {
          if (!ov || ov.style.display === "none") return;
          if (e.key === "Escape") closePanel();
          if (e.key !== "Tab") e.stopImmediatePropagation();
        },
        true,
      );
    }
    drawPanel();
    ov.style.display = "flex";
  }

  /* pemulihan di luar battle: perlahan, dan penuh bila hero pulih penuh (penginapan, naik level, dsb.) */
  let lastHero = null;
  setInterval(() => {
    try {
      refreshBtn();
      if (!joined() || btOn || DB.stash || typeof Pl === "undefined" || !Pl.hp) return;
      const full = Pl.hp >= mhp();
      bothK.forEach((k) => {
        const d = rec(k);
        if (full && lastHero !== null && lastHero < mhp()) {
          d.hp = mhpOf(k, d);
          d.mp = mmpOf(k, d);
        } else {
          d.hp = Math.min(mhpOf(k, d), d.hp + Math.max(1, mhpOf(k, d) * 0.005));
          d.mp = Math.min(mmpOf(k, d), d.mp + mmpOf(k, d) * 0.02);
        }
      });
      lastHero = Pl.hp;
      if (ov && ov.style.display !== "none") drawPanel();
    } catch (e) {}
  }, 1000);

  /* API untuk enemy_ai.js (+ akses data) */
  globalThis.DUOBT = {
    list: () => (ensure(), DB.list.filter((u) => u.hp > 0).map((u) => ({ id: u.id, x: u.x }))),
    attack: attackUnit,
    units: () => DB.list,
    cfg: BC,
    data: rec,
    statUp: statUpD,
    reset: resetD,
    auto: autoD,
    potion: potD,
    openPanel,
    calc: { mhp: mhpOf, mmp: mmpOf, pwr: pwrOf, crit: critOf, pen: penOf },
  };
  refreshBtn();

  console.info("[duo_lyra_selena] siap: ROSTER =", ROSTER.length, "anggota");
})();
